//
//  IdiomDictionary.swift
//  Aidoku
//
//  Curated multi-word-expression dictionaries for languages the Learner supports
//  (en/de/tr). Used by HeuristicMWEDetectionService when the Foundation Models
//  detector is unavailable (devices without Apple Intelligence).
//

import Foundation

/// A single dictionary entry. `lemmas` is the canonical token sequence the
/// detector matches against. For agglutinative languages (Turkish), set
/// `stemTolerant = true` so matching accepts tokens whose surface or NLTagger
/// lemma is prefixed by the pattern token — covers the heavy suffix stacking
/// that NLTagger doesn't always strip.
struct IdiomEntry: Sendable {
    let canonical: String
    let lemmas: [String]
    let kind: PhraseKind
    let stemTolerant: Bool
}

enum IdiomDictionary {

    /// Returns the dictionary for the BCP-47 language tag's primary subtag.
    /// Tags like `en-US`, `de-DE`, `tr-TR` map to the language list.
    static func entries(for languageTag: String) -> [IdiomEntry] {
        let primary = String(languageTag.split(separator: "-").first ?? Substring(languageTag)).lowercased()
        switch primary {
        case "en": return english
        case "de": return german
        case "tr": return turkish
        default:   return []
        }
    }

